-- The database as version 1 (Tellycine 1.0 to 1.9) created it, for testing migrations from it.
CREATE TABLE IF NOT EXISTS `playlists` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `url` TEXT NOT NULL, `username` TEXT NOT NULL, `password` TEXT NOT NULL, `epgUrl` TEXT NOT NULL, `detectedEpgUrl` TEXT NOT NULL, `userAgent` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `lastSyncedAt` INTEGER, `epgSyncedAt` INTEGER, `syncState` TEXT NOT NULL, `syncMessage` TEXT, `liveCount` INTEGER NOT NULL, `movieCount` INTEGER NOT NULL, `seriesCount` INTEGER NOT NULL, `programmeCount` INTEGER NOT NULL, `expiresAt` INTEGER, `maxConnections` INTEGER, `connectionLimit` INTEGER, `serverTimezone` TEXT, `serverSoftware` TEXT, `vodEnabled` INTEGER NOT NULL DEFAULT 1, `dvrApiKey` TEXT, `dvrUsername` TEXT);
CREATE TABLE IF NOT EXISTS `categories` (`playlistId` INTEGER NOT NULL, `kind` TEXT NOT NULL, `categoryId` TEXT NOT NULL, `name` TEXT NOT NULL, `sortOrder` INTEGER NOT NULL, `itemCount` INTEGER NOT NULL, PRIMARY KEY(`playlistId`, `kind`, `categoryId`));
CREATE INDEX IF NOT EXISTS `index_categories_playlistId_kind_sortOrder` ON `categories` (`playlistId`, `kind`, `sortOrder`);
CREATE TABLE IF NOT EXISTS `streams` (`playlistId` INTEGER NOT NULL, `kind` TEXT NOT NULL, `streamId` TEXT NOT NULL, `name` TEXT NOT NULL, `sortOrder` INTEGER NOT NULL, `categoryId` TEXT, `logo` TEXT, `url` TEXT NOT NULL, `epgChannelId` TEXT, `number` INTEGER, `containerExt` TEXT, `rating` REAL, `year` TEXT, `plot` TEXT, `genre` TEXT, `addedAt` INTEGER, `catchupDays` INTEGER, `catchupType` TEXT, `catchupSource` TEXT, `backdrop` TEXT, `userAgent` TEXT, `referrer` TEXT, PRIMARY KEY(`playlistId`, `kind`, `streamId`));
CREATE INDEX IF NOT EXISTS `index_streams_playlistId_kind_sortOrder` ON `streams` (`playlistId`, `kind`, `sortOrder`);
CREATE INDEX IF NOT EXISTS `index_streams_playlistId_kind_categoryId_sortOrder` ON `streams` (`playlistId`, `kind`, `categoryId`, `sortOrder`);
CREATE INDEX IF NOT EXISTS `index_streams_playlistId_epgChannelId` ON `streams` (`playlistId`, `epgChannelId`);
CREATE TABLE IF NOT EXISTS `episodes` (`playlistId` INTEGER NOT NULL, `episodeId` TEXT NOT NULL, `seriesId` TEXT NOT NULL, `season` INTEGER NOT NULL, `episode` INTEGER NOT NULL, `title` TEXT NOT NULL, `url` TEXT NOT NULL, `logo` TEXT, PRIMARY KEY(`playlistId`, `episodeId`));
CREATE INDEX IF NOT EXISTS `index_episodes_playlistId_seriesId_season_episode` ON `episodes` (`playlistId`, `seriesId`, `season`, `episode`);
CREATE TABLE IF NOT EXISTS `programmes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlistId` INTEGER NOT NULL, `channelId` TEXT NOT NULL, `startMs` INTEGER NOT NULL, `stopMs` INTEGER NOT NULL, `title` TEXT NOT NULL, `description` TEXT, `category` TEXT);
CREATE INDEX IF NOT EXISTS `index_programmes_playlistId_channelId_startMs` ON `programmes` (`playlistId`, `channelId`, `startMs`);
CREATE TABLE IF NOT EXISTS `favorites` (`playlistId` INTEGER NOT NULL, `kind` TEXT NOT NULL, `streamId` TEXT NOT NULL, `addedAt` INTEGER NOT NULL, PRIMARY KEY(`playlistId`, `kind`, `streamId`));
CREATE TABLE IF NOT EXISTS `history` (`playlistId` INTEGER NOT NULL, `itemKey` TEXT NOT NULL, `kind` TEXT NOT NULL, `streamId` TEXT NOT NULL, `title` TEXT NOT NULL, `subtitle` TEXT, `artwork` TEXT, `url` TEXT NOT NULL, `positionMs` INTEGER NOT NULL, `durationMs` INTEGER NOT NULL, `lastWatchedAt` INTEGER NOT NULL, PRIMARY KEY(`playlistId`, `itemKey`));
CREATE INDEX IF NOT EXISTS `index_history_playlistId_lastWatchedAt` ON `history` (`playlistId`, `lastWatchedAt`);
CREATE TABLE IF NOT EXISTS `hidden_categories` (`playlistId` INTEGER NOT NULL, `kind` TEXT NOT NULL, `categoryId` TEXT NOT NULL, PRIMARY KEY(`playlistId`, `kind`, `categoryId`));
CREATE TABLE IF NOT EXISTS `downloads` (`playlistId` INTEGER NOT NULL, `itemKey` TEXT NOT NULL, `kind` TEXT NOT NULL, `streamId` TEXT NOT NULL, `title` TEXT NOT NULL, `subtitle` TEXT, `artwork` TEXT, `sourceUrl` TEXT NOT NULL, `userAgent` TEXT, `referrer` TEXT, `filePath` TEXT NOT NULL, `systemId` INTEGER NOT NULL, `status` TEXT NOT NULL, `bytesDownloaded` INTEGER NOT NULL, `bytesTotal` INTEGER NOT NULL, `error` TEXT, `createdAt` INTEGER NOT NULL, `completedAt` INTEGER, PRIMARY KEY(`playlistId`, `itemKey`));
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
